10.1.1.3           ge-0/0/0.0         3.3.3.3:0           11$$::text, $$[{"id": "A", "text": "1", "is_correct": false}, {"id": "B", "text": "2", "is_correct": true}, {"id": "C", "text": "3", "is_correct": false}, {"id": "D", "text": "0", "is_correct": false}]$$::jsonb, $$The output lists two LDP neighbors.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$4.0 MPLS$$::text, 15.0, '2d674277d3b8f904', true) ON CONFLICT (id) DO NOTHING;
