INSERT INTO questions (id, exam_id, track_id, question_type, difficulty, bloom_level, body, options, explanation, reference_urls, blueprint_section, blueprint_weight, content_hash, is_active) VALUES ('9069e1e8-a472-5f4e-9db4-ac8d1c8d6e3b', 'b0000000-0000-0000-0000-000000000013', 'a0000000-0000-0000-0000-000000000002', 'single-choice', 4, 'analyze', $$An IS-IS Level 1 router needs to reach a prefix in another area. The nearest L1/L2 router has the attached bit set. What is the expected result?$$::text, $$[{"id": "A", "text": "The L1 router installs a default route toward the L1/L2 router.", "is_correct": true}, {"id": "B", "text": "LOCAL_PREF is evaluated before AS_PATH; the higher LOCAL_PREF route wins.", "is_correct": false}, {"id": "C", "text": "BGP advertises the new site ID and pseudowire labels to other PEs.", "is_correct": false}, {"id": "D", "text": "The DR builds the shared tree toward the RP using (*,239.1.1.1).", "is_correct": false}]$$::jsonb, $$Given An IS-IS Level 1 router needs to reach a prefix in another area. and The nearest L1/L2 router has the attached bit set., the result is: The L1 router installs a default route toward the L1/L2 router.$$::text, $${"https://www.juniper.net/us/en/training/certification/certification-tracks/jncip-sp.html"}$$::text[], $$2.0 IS-IS$$::text, 15.0, 'e9f662c8ed4c32e1', true) ON CONFLICT (id) DO NOTHING;
